def _decode_component(s: str) -> str:
    # '+' represents a space in query strings
    s = s.replace('+', ' ')
    if '%' not in s:
        return s

    parts = s.split('%')
    res = bytearray(parts[0].encode('utf-8'))
    for part in parts[1:]:
        if len(part) < 2:
            raise ValueError(f"Malformed percent-escape: incomplete escape '%{part}'")
        hex_code = part[:2]
        try:
            res.append(int(hex_code, 16))
        except ValueError:
            raise ValueError(f"Malformed percent-escape: invalid hex digits '%{hex_code}'")
        res.extend(part[2:].encode('utf-8'))

    return res.decode('utf-8')


def parse_query(qs: str) -> dict:
    result = {}
    for pair in qs.split('&'):
        if not pair:
            continue
        key, sep, value = pair.partition('=')
        decoded_key = _decode_component(key)
        decoded_val = _decode_component(value) if sep else ''
        result.setdefault(decoded_key, []).append(decoded_val)
    return result
